using BarberSync.Application.Abstractions;using Microsoft.AspNetCore.Mvc;using Npgsql;using System.Text.Json;
namespace BarberSync.Api.Controllers;
[ApiController,Route("api/client-portal/admin")]public sealed class ClientPortalAdminController(IConfiguration configuration,ICurrentUserContext current):ControllerBase
{
 [HttpGet("dashboard")]public async Task<IActionResult> Dashboard(CancellationToken ct){var cs=configuration.GetConnectionString("DefaultConnection")??throw new InvalidOperationException("ConnectionStrings:DefaultConnection não foi configurada.");await using var c=new NpgsqlConnection(cs);await c.OpenAsync(ct);await using var cmd=new NpgsqlCommand(@"select jsonb_build_object('recentAccesses',coalesce((select jsonb_agg(jsonb_build_object('clientName',cl.name,'eventType',e.event_type,'createdAt',e.created_at) order by e.created_at desc) from (select * from barber.client_portal_events where tenant_id=@tenant and branch_id=@branch order by created_at desc limit 20)e join barber.clients cl on cl.id=e.client_id),'[]'),'openSupport',coalesce((select jsonb_agg(jsonb_build_object('clientName',cl.name,'subject',r.subject,'category',r.category,'priority',r.priority,'status',r.status,'createdAt',r.created_at) order by r.created_at desc) from barber.client_support_requests r join barber.clients cl on cl.id=r.client_id where r.tenant_id=@tenant and r.branch_id=@branch and r.status not in('Resolved','Cancelled')),'[]'),'reviews',coalesce((select jsonb_agg(jsonb_build_object('clientName',cl.name,'rating',r.rating,'npsScore',r.nps_score,'comment',r.comment,'status',r.status,'submittedAt',r.submitted_at) order by r.created_at desc) from barber.client_reviews r join barber.clients cl on cl.id=r.client_id where r.tenant_id=@tenant and r.branch_id=@branch),'[]'),'pendingPayments',(select count(*) from barber.client_payment_requests where tenant_id=@tenant and branch_id=@branch and status='Pending'),'sourceStatus','available')",c);cmd.Parameters.AddWithValue("tenant",current.TenantId);cmd.Parameters.AddWithValue("branch",current.BranchId);var raw=await cmd.ExecuteScalarAsync(ct);var data=JsonDocument.Parse(raw?.ToString()??"{}").RootElement.Clone();return Ok(new{success=true,data,traceId=HttpContext.TraceIdentifier});}
}
